public int[] stockSpan(int[] prices) {
    int n = prices.length;
    int[] span = new int[n];
    for (int i = 0; i < n; i++) {
        int count = 1;
        int j = i - 1;
        while (j >= 0 && prices[j] <= prices[i]) {
            count++;
            j--;
        }
        span[i] = count;
    }
    return span;
}

public int[] stockSpan(int[] prices) {
    int n = prices.length;
    int[] span = new int[n];
    Deque<int[]> stack = new ArrayDeque<>(); // each entry: {price, span}
    for (int i = 0; i < n; i++) {
        int s = 1;
        while (!stack.isEmpty() && stack.peek()[0] <= prices[i]) {
            s += stack.pop()[1];   // absorb the popped day's whole span
        }
        stack.push(new int[]{prices[i], s});
        span[i] = s;
    }
    return span;
}

