def stock_span(self, prices: list[int]) -> list[int]:
    span = []
    stack: list[tuple[int, int]] = []  # (price, span)
    for price in prices:
        s = 1
        while stack and stack[-1][0] <= price:
            s += stack.pop()[1]        # absorb the popped day's span
        stack.append((price, s))
        span.append(s)
    return span

